-- 000885_site_pages.up.sql
-- Seeds the public company/legal pages (About, Contact, FAQ, Privacy,
-- Terms, Community Rules, Cookies, Trust & Safety) as published Page
-- Builder pages rendered at /{slug} via GET /api/v1/pages/{slug}, plus the
-- 'contact' public form backing the contact page's form_embed block.
-- Also publishes the seeded 'feedback' and 'report' system forms — their
-- public embeds (GET /forms/{slug}/embed) 404 until status='published',
-- which left /feedback rendering empty — and adds the missing 'Details'
-- field so the feedback form actually captures a message.
--
-- Ref: .jeos/sections/16-page-builder.md (block schema), §06 (forms)

BEGIN;

-- ── 1. Contact form ─────────────────────────────────────────────────────
-- status='published' is required by GetFormEmbed; submissions go to
-- POST /api/v1/forms/{id}/submissions (public, optional auth).

INSERT INTO forms (id, name, slug, description, is_multi_step, submit_label, success_message, status, is_system, form_type)
VALUES (
	'00000000-0000-0000-0000-0000000000c1',
	'Contact Us',
	'contact',
	'General enquiries, account support, partnerships and privacy requests from the /contact page.',
	false,
	'Send message',
	'Thanks — your message has been received. We typically reply within 2 business days.',
	'published',
	true,
	'standard'
)
ON CONFLICT (slug) DO UPDATE SET
	name = EXCLUDED.name,
	description = EXCLUDED.description,
	submit_label = EXCLUDED.submit_label,
	success_message = EXCLUDED.success_message,
	status = 'published';

INSERT INTO custom_field_groups (id, name, slug, description, is_system)
VALUES (
	'00000000-0000-0000-0000-0000000000c2',
	'Contact Form Fields',
	'form-contact',
	'Fields for the public /contact page form.',
	true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO custom_field_group_assignments (group_id, entity_class, entity_id, position)
SELECT '00000000-0000-0000-0000-0000000000c2', 'form', '00000000-0000-0000-0000-0000000000c1', 0
WHERE NOT EXISTS (
	SELECT 1 FROM custom_field_group_assignments
	WHERE group_id = '00000000-0000-0000-0000-0000000000c2'
	  AND entity_class = 'form'
	  AND entity_id = '00000000-0000-0000-0000-0000000000c1'
);

INSERT INTO custom_fields (id, group_id, label, key, field_type, options, is_required, is_system, show_in_frontend, position)
VALUES
	('00000000-0000-0000-0000-0000000000d1', '00000000-0000-0000-0000-0000000000c2', 'Full name',     'full_name', 'text',     NULL,                    true, true, true, 0),
	('00000000-0000-0000-0000-0000000000d2', '00000000-0000-0000-0000-0000000000c2', 'Email address', 'email',     'email',    NULL,                    true, true, true, 1),
	('00000000-0000-0000-0000-0000000000d3', '00000000-0000-0000-0000-0000000000c2', 'Topic',         'topic',     'select',   '[{"label": "General enquiry", "value": "general-enquiry"}, {"label": "Account & sign-in", "value": "account-sign-in"}, {"label": "Billing & credits", "value": "billing-credits"}, {"label": "Partnerships & press", "value": "partnerships-press"}, {"label": "Privacy & data", "value": "privacy-data"}, {"label": "Report abuse", "value": "report-abuse"}]'::jsonb, true, true, true, 2),
	('00000000-0000-0000-0000-0000000000d4', '00000000-0000-0000-0000-0000000000c2', 'Message',       'message',   'textarea', NULL,                    true, true, true, 3)
ON CONFLICT (group_id, key) DO NOTHING;

-- Field permissions: every group can view (required for the public embed —
-- GetFormEmbed narrows to guest can_view + show_in_frontend); non-guest
-- groups can edit. Matches the 000859/000860 convention.
INSERT INTO custom_field_permissions (field_id, user_group_id, can_view, can_edit)
SELECT f.id, ug.id, true, ug.slug <> 'guest'
FROM custom_fields f
CROSS JOIN user_groups ug
WHERE f.group_id = '00000000-0000-0000-0000-0000000000c2'
ON CONFLICT (field_id, user_group_id) DO NOTHING;

-- ── 2. Publish the seeded public forms ──────────────────────────────────
-- GetFormEmbed returns form_not_published unless status='published'; the
-- baseline seed used 'active', leaving /feedback empty. 'report' powers
-- the abuse-report embed referenced from /rules and /safety.

UPDATE forms SET status = 'published' WHERE slug IN ('feedback', 'report') AND status <> 'published';

-- The feedback form's public field group only had a Category select — add
-- the missing free-text field so submissions carry an actual message.
INSERT INTO custom_fields (id, group_id, label, key, field_type, is_required, is_system, show_in_frontend, position)
SELECT '00000000-0000-0000-0000-0000000000d5', '00000000-0000-0000-0000-000000000050', 'Details', 'details', 'textarea', true, true, true, 1
WHERE EXISTS (SELECT 1 FROM custom_field_groups WHERE id = '00000000-0000-0000-0000-000000000050')
ON CONFLICT (group_id, key) DO NOTHING;

INSERT INTO custom_field_permissions (field_id, user_group_id, can_view, can_edit)
SELECT f.id, ug.id, true, ug.slug <> 'guest'
FROM custom_fields f
CROSS JOIN user_groups ug
WHERE f.id = '00000000-0000-0000-0000-0000000000d5'
ON CONFLICT (field_id, user_group_id) DO NOTHING;

-- ── 3. Published pages ──────────────────────────────────────────────────
-- The baseline smoke-test 'about-us' page is replaced by the real About
-- page at the canonical /about slug (the main_footer menu links /about).

UPDATE pages SET slug = 'about' WHERE slug = 'about-us'
	AND NOT EXISTS (SELECT 1 FROM pages WHERE slug = 'about');
DELETE FROM pages WHERE slug = 'about-us';


INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'About Us', 'about', 'Japa.to is the community platform for people planning, making and settling into an international move — verified guides, real answers and tools for every stage.', 'about', 'published', '[{"id": "about-hero", "type": "hero", "visible": true, "props": {"eyebrow": "About Japa.to", "headline": "Every move abroad is easier when someone has done it before you.", "highlight": "done it before you.", "subhead": "Japa.to is the community platform for people planning, making, and settling into an international move — from the first late-night search to the day the new place finally feels like home.", "layout": "split", "media": {"media_id": "", "url": "/illustrations/about.svg", "alt": "Illustration of a globe with a flight path connecting community members"}, "ctas": [{"label": "Join the community", "href": "/signup", "variant": "primary"}, {"label": "Explore destinations", "href": "/explore", "variant": "ghost"}], "stats": [{"value": "7", "label": "journey stages, one platform"}, {"value": "100+", "label": "destination & origin spaces"}, {"value": "24/7", "label": "community across time zones"}], "trust_text": "Free to join. Built for movers, by movers."}}, {"id": "about-mission-h", "type": "heading", "visible": true, "props": {"text": "Why we exist", "level": "h2", "size": "xl", "align": "center", "eyebrow": "Our mission", "subheading": "Relocating is one of life''s biggest decisions — and most people make it with scattered information and no one to ask."}}, {"id": "about-mission", "type": "content", "visible": true, "props": {"html": "\n<p><strong>Japa</strong> — a word born from Yoruba, now shorthand across West Africa and beyond for leaving home to build a better life elsewhere — is equal parts hope and paperwork. The people who need help most often rely on WhatsApp rumours, paid agents, and scattered forum threads.</p>\n<p>We built Japa.to to change that. It is a single, trusted home where people at every stage of the journey — dreaming, researching, applying, arriving, settling — can find verified guides, honest answers from people who have done it, and tools that turn a scary process into a checklist.</p>\n<p>No guaranteed-visa salespeople. No recycled misinformation. Just a community that remembers what the first step felt like.</p>\n", "prose_style": "article"}}, {"id": "about-offer-h", "type": "heading", "visible": true, "props": {"text": "Everything in one place", "level": "h2", "size": "xl", "align": "center", "eyebrow": "What you get", "subheading": "The pieces of a move that used to live in ten different apps and a hundred browser tabs."}}, {"id": "about-offer", "type": "card_grid", "visible": true, "props": {"cards": [{"icon": "Users", "title": "Community spaces", "description": "Country, city, university and interest spaces where members share real experiences — not adverts.", "cta": {"label": "Browse spaces", "href": "/spaces", "variant": "link"}}, {"icon": "BookOpen", "title": "Destination wiki", "description": "Community-maintained guides on visas, housing, healthcare and daily life — versioned and reviewed.", "cta": {"label": "Read the wiki", "href": "/wiki", "variant": "link"}}, {"icon": "Compass", "title": "Planning tools", "description": "Checklists, cost-of-living comparisons, scholarship finders and timeline trackers that turn anxiety into a plan.", "cta": {"label": "See the tools", "href": "/tools", "variant": "link"}}, {"icon": "GraduationCap", "title": "Japa Academy", "description": "Structured courses and tracks that walk you through applications, documents and arrival.", "cta": {"label": "Start learning", "href": "/academy", "variant": "link"}}, {"icon": "MessagesSquare", "title": "Ask an expat", "description": "AMA threads and mentorship matching with people already living where you want to go.", "cta": {"label": "Find a mentor", "href": "/mentors", "variant": "link"}}, {"icon": "Heart", "title": "Story wall", "description": "Real relocation stories — the wins, the setbacks and the honest in-between.", "cta": {"label": "Read stories", "href": "/stories", "variant": "link"}}], "card_variant": "feature", "layout": "grid", "columns": 3, "responsive_columns": {"tablet": 2, "mobile": 1}}}, {"id": "about-journey-h", "type": "heading", "visible": true, "props": {"text": "Built around the real journey", "level": "h2", "size": "xl", "align": "center", "eyebrow": "How it works", "subheading": "Your profile, feed and tools adapt to where you are — not where someone else thinks you should be."}}, {"id": "about-journey", "type": "timeline", "visible": true, "props": {"steps": [{"icon": "CloudSun", "title": "Considering", "description": "Exploring the idea. Compare destinations, read stories, find out what a move really costs."}, {"icon": "Map", "title": "Planning", "description": "Picking a route and building the plan — visa options, budgets, timelines, checklists."}, {"icon": "FileCheck", "title": "Preparing", "description": "Documents assembled, application drafted, requirements checked off one by one."}, {"icon": "Send", "title": "Applied", "description": "Application submitted — now it''s biometrics, interviews and the waiting game."}, {"icon": "BadgeCheck", "title": "Approved", "description": "Yes in hand. Now the logistics: housing, banking, packing, goodbyes."}, {"icon": "PlaneLanding", "title": "Relocated", "description": "First weeks in a new country. Arrival checklists and local spaces for the things nobody warns you about."}, {"icon": "Home", "title": "Settled", "description": "Bank accounts, registrations, your people. You made it — now you''re who a newcomer needs."}], "layout": "vertical"}}, {"id": "about-values-h", "type": "heading", "visible": true, "props": {"text": "What we stand for", "level": "h2", "size": "xl", "align": "center"}}, {"id": "about-values", "type": "card_grid", "visible": true, "props": {"cards": [{"icon": "HeartHandshake", "title": "Community first", "description": "Answers come from people who have actually done it — not content farms. Every feature is built to strengthen peer help."}, {"icon": "BadgeCheck", "title": "Information you can trust", "description": "Guides are versioned, reviewed and dated. When rules change, the page changes — and says when it did."}, {"icon": "Lock", "title": "Privacy by design", "description": "Your documents and plans are yours. Granular controls, no data brokerage, and a real delete-my-data path."}, {"icon": "Globe", "title": "Built by migrants", "description": "The team behind Japa.to has lived this journey. We build what we needed when we moved."}], "card_variant": "feature", "layout": "grid", "columns": 2, "responsive_columns": {"tablet": 2, "mobile": 1}}}, {"id": "about-quote", "type": "quote", "visible": true, "props": {"quote": "Nobody should have to figure out a new country alone. Japa.to exists so they do not have to.", "author": "The Japa.to team", "layout": "centered"}}, {"id": "about-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Start your journey today", "subhead": "Create a free account and join a community that has been exactly where you are.", "ctas": [{"label": "Create free account", "href": "/signup", "variant": "primary"}, {"label": "See how it works", "href": "/faq", "variant": "ghost"}], "alignment": "center"}}]'::jsonb, '{"title": "About Us — Japa.to", "description": "The community platform for international moves: destination spaces, a maintained wiki, planning tools, academy courses and mentorship — built by migrants, for movers."}'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET
	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Contact Us', 'contact', 'Questions, feedback, partnerships or a problem with your account — pick a channel or send us a message; we reply within 2 business days.', 'page', 'published', '[{"id": "contact-hero", "type": "hero", "visible": true, "props": {"eyebrow": "Contact us", "headline": "Talk to a human. We actually answer.", "subhead": "Questions, feedback, partnership ideas or a problem with your account — pick the channel that fits and we will take it from there.", "layout": "split", "media": {"media_id": "", "url": "/illustrations/contact.svg", "alt": "Illustration of an envelope with conversation bubbles"}, "ctas": [{"label": "Browse the FAQ first", "href": "/faq", "variant": "ghost"}]}}, {"id": "contact-channels", "type": "card_grid", "visible": true, "props": {"cards": [{"icon": "LifeBuoy", "title": "Support & account help", "description": "Sign-in problems, billing, profile issues or anything broken — use the form below and it lands in our support queue."}, {"icon": "ShieldAlert", "title": "Report a scam or abuse", "description": "Seen a suspicious visa offer, fake agent or abusive content? Reports go to our moderation team.", "cta": {"label": "Report now", "href": "/scam-alerts", "variant": "link"}}, {"icon": "MessageSquare", "title": "Product feedback", "description": "Ideas, feature requests and bug reports shape the roadmap — tell us what to build next.", "cta": {"label": "Give feedback", "href": "/feedback", "variant": "link"}}, {"icon": "Briefcase", "title": "Partnerships & press", "description": "Universities, employers, community organisations and media — pick ''Partnerships & press'' on the form below.", "cta": {"label": "Contact us", "href": "/contact", "variant": "link"}}], "card_variant": "feature", "layout": "grid", "columns": 2, "responsive_columns": {"tablet": 2, "mobile": 1}}}, {"id": "contact-form", "type": "form_embed", "visible": true, "props": {"preset": "contact", "form_slug": "contact", "title": "Send us a message", "subtitle": "Fill this in and it goes straight to the team. We typically reply within 2 business days.", "submit_endpoint": "/api/v1/forms/00000000-0000-0000-0000-0000000000c1/submissions", "submit_label": "Send message", "success_message": "Thanks — your message is in. Keep an eye on your inbox; we reply within 2 business days.", "error_message": "Something went wrong sending your message. Please try again — if it keeps failing, email support@japa.to.", "fields": [{"name": "full_name", "label": "Full name", "type": "text", "required": true, "placeholder": "Your name"}, {"name": "email", "label": "Email address", "type": "email", "required": true, "placeholder": "you@example.com"}, {"name": "topic", "label": "Topic", "type": "select", "required": true, "options": ["General enquiry", "Account & sign-in", "Billing & credits", "Partnerships & press", "Privacy & data", "Report abuse"]}, {"name": "message", "label": "Message", "type": "textarea", "required": true, "placeholder": "Tell us what is going on — links and screenshots help."}]}}, {"id": "contact-notes", "type": "content", "visible": true, "props": {"html": "\n<h3>Before you write</h3>\n<ul>\n  <li><strong>Quick answers:</strong> most questions are already covered in the <a href=\"/faq\">FAQ</a> or the <a href=\"/docs\">docs</a>.</li>\n  <li><strong>Account security:</strong> we will never ask for your password, one-time codes or wallet PIN — in email or anywhere else.</li>\n  <li><strong>Response times:</strong> support messages are answered within 2 business days; abuse and scam reports are triaged daily.</li>\n  <li><strong>Privacy requests:</strong> for data access, correction or deletion you can also use the self-serve tools in <a href=\"/settings\">Settings</a> — see the <a href=\"/privacy\">Privacy Policy</a> for details.</li>\n</ul>\n", "prose_style": "minimal"}}, {"id": "contact-cta", "type": "cta_banner", "visible": true, "props": {"headline": "In a hurry?", "subhead": "The FAQ covers accounts, posting, spaces, tools and privacy in plain language.", "ctas": [{"label": "Open the FAQ", "href": "/faq", "variant": "primary"}], "alignment": "center"}}]'::jsonb, '{"title": "Contact Us — Japa.to", "description": "Reach the Japa.to team: support, scam reports, product feedback, partnerships and privacy requests."}'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET
	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Frequently Asked Questions', 'faq', 'Answers to the most common questions about accounts, spaces, tools, learning and safety on Japa.to.', 'page', 'published', '[{"id": "faq-hero", "type": "hero", "visible": true, "props": {"eyebrow": "Help centre", "headline": "Frequently asked questions", "subhead": "Everything about using Japa.to — accounts, communities, tools, payments and safety. Pick a topic below or contact us if your question is not covered.", "layout": "split", "media": {"media_id": "", "url": "/illustrations/faq.svg", "alt": "Illustration of question and answer speech bubbles"}, "ctas": [{"label": "Contact support", "href": "/contact", "variant": "ghost"}]}}, {"id": "faq-tabs", "type": "tabs", "visible": true, "props": {"tabs": [{"label": "Getting started", "icon": "Rocket", "content_blocks": [{"id": "faq-getting", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "What is Japa.to?", "content_blocks": [{"id": "faq-getting-a0", "type": "content", "visible": true, "props": {"html": "<p>Japa.to is the community platform for people planning, making or settling into an international move. It combines destination communities, a collaboratively maintained wiki, planning tools, structured learning tracks and mentorship — so the whole relocation journey lives in one place.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Who is Japa.to for?", "content_blocks": [{"id": "faq-getting-a1", "type": "content", "visible": true, "props": {"html": "<p>Anyone at any stage of an international move: people still dreaming, applicants mid-paperwork, new arrivals, and long-settled expats who want to help the next person. The word ''japa'' comes from a Nigerian term for emigrating, but the community is open to movers of every origin and destination.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Is Japa.to free to use?", "content_blocks": [{"id": "faq-getting-a2", "type": "content", "visible": true, "props": {"html": "<p>Yes. Creating an account, joining spaces, posting, reading the wiki and using the core planning tools are free. Some optional extras — highlighted listings, certain premium actions — use credits, which are always clearly priced before you spend them.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Do I need an account to browse?", "content_blocks": [{"id": "faq-getting-a3", "type": "content", "visible": true, "props": {"html": "<p>Most public content — spaces, blog posts, wiki pages, forum threads and the FAQ — is readable without an account. You need a free account to post, comment, follow spaces, save checklists, join planning groups or message other members.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I create an account?", "content_blocks": [{"id": "faq-getting-a4", "type": "content", "visible": true, "props": {"html": "<p>Click <a href=\"/signup\">Sign up</a>, register with your email or a social sign-in, verify your email and pick a username. Onboarding asks about your journey stage and destinations so your feed is useful from day one — you can change it later in Settings.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I find my destination''s community?", "content_blocks": [{"id": "faq-getting-a5", "type": "content", "visible": true, "props": {"html": "<p>Open <a href=\"/explore\">Explore</a> or <a href=\"/spaces\">Spaces</a> and search for your destination country, city or university. Follow the space to get its posts in your feed. Many destinations also have a wiki section and local sub-communities.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Community & content", "icon": "Users", "content_blocks": [{"id": "faq-community", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "What are spaces?", "content_blocks": [{"id": "faq-community-a0", "type": "content", "visible": true, "props": {"html": "<p>Spaces are communities inside Japa.to — organised by country, city, university, profession or interest. Each space has its own feed, forum, members and moderators. Following a space is how you tune your timeline.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the destination wiki and who edits it?", "content_blocks": [{"id": "faq-community-a1", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/wiki\">destination wiki</a> is a community-maintained knowledge base covering visas, housing, healthcare, banking and daily life per destination. Pages are versioned and dated; experienced members can propose edits that are reviewed before publishing — so information stays current and accountable.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I follow specific topics?", "content_blocks": [{"id": "faq-community-a2", "type": "content", "visible": true, "props": {"html": "<p>Browse <a href=\"/tags\">tags</a> to follow subjects across spaces — e.g. #studentvisa or #jobsearch — and get matching posts in your feed without joining every space.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the difference between the forum, blog and stories?", "content_blocks": [{"id": "faq-community-a3", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/forum\">forum</a> is for questions and threaded discussion — vote rails, Best/Top/New sorting, marked solutions. The <a href=\"/blog\">blog</a> hosts long-form articles and series. The <a href=\"/stories\">story wall</a> is for personal relocation narratives — the wins and the honest setbacks.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How does my feed work?", "content_blocks": [{"id": "faq-community-a4", "type": "content", "visible": true, "props": {"html": "<p>Your home timeline has a Following view (spaces and people you follow) and a For You view (ranked by relevance, trending activity and your journey stage). The <a href=\"/digest\">digest</a> summarizes what you missed.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I post?", "content_blocks": [{"id": "faq-community-a5", "type": "content", "visible": true, "props": {"html": "<p>Use the Compose button, pick a content type (discussion, question, story, article), choose a space, and write. The editor supports @mentions, #tags, rich text, images and embeds. Required-space rules mean every post lands where the right people will see it.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Can I save posts for later?", "content_blocks": [{"id": "faq-community-a6", "type": "content", "visible": true, "props": {"html": "<p>Yes — bookmark any post or wiki page to your <a href=\"/bookmarks\">bookmarks</a>, and organize saved items into lists. Everything is synced to your account.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do messages and notifications work?", "content_blocks": [{"id": "faq-community-a7", "type": "content", "visible": true, "props": {"html": "<p>Direct messages let you talk one-to-one (mentorship connections open a thread automatically). <a href=\"/notifications\">Notifications</a> cover replies, mentions, follows and moderation updates — tune what you get in Settings → Notifications.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What are planning groups and mutual aid?", "content_blocks": [{"id": "faq-community-a8", "type": "content", "visible": true, "props": {"html": "<p><a href=\"/planning-groups\">Planning groups</a> are small private groups of people moving to the same destination around the same time, with shared milestones and check-ins. The <a href=\"/mutual-aid\">mutual aid board</a> is for needs, offers and skill swaps — rides, document reviews, temporary storage and the like.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Journeys & tools", "icon": "Wrench", "content_blocks": [{"id": "faq-tools", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "What are journey stages?", "content_blocks": [{"id": "faq-tools-a0", "type": "content", "visible": true, "props": {"html": "<p>Your profile carries a <a href=\"/japa-stage\">japa stage</a> — Considering, Planning, Preparing, Applied, Approved, Relocated or Settled. It shapes what content and tools are surfaced to you, and tells the community how to help. Shorter trips use the same arc ending in Traveled and Returned. Update your stage in your profile as you move forward.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What planning tools are included?", "content_blocks": [{"id": "faq-tools-a1", "type": "content", "visible": true, "props": {"html": "<p>Under <a href=\"/tools\">Tools</a>: a visa checklist builder, readiness assessment, cost-of-living comparison, scholarship finder, remittance rate tracker, credential checker, CV formatter, housing guide, attestation guide, language test hub, tax calculator, arrival checklist, processing-time tracker, visa-route comparison and a community locator. All free; all guides — not legal or immigration advice.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I compare universities or destinations?", "content_blocks": [{"id": "faq-tools-a2", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/universities\">universities directory</a> has country, ranking, tuition and programme data — open <a href=\"/compare\">Compare</a> to put options side by side. Destination spaces carry the same comparison for cost of living and daily life.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I find scholarships?", "content_blocks": [{"id": "faq-tools-a3", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/scholarships\">scholarship finder</a> searches live funding opportunities filtered by destination, level and field — the deadline calendar reminds you before they close.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How does the visa checklist work?", "content_blocks": [{"id": "faq-tools-a4", "type": "content", "visible": true, "props": {"html": "<p>Pick a destination and visa route and the checklist generates the required documents and steps. Your progress is saved to your account — or kept anonymously for guests until you sign up.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the visa timeline tracker?", "content_blocks": [{"id": "faq-tools-a5", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/visa-timelines\">timeline tracker</a> lets you log each milestone of your application (submitted, biometrics, decision) and optionally share it anonymously — the community''s shared timelines show real processing times per route.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the community calendar?", "content_blocks": [{"id": "faq-tools-a6", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/calendar\">calendar</a> collects dates that matter — embassy appointment windows, scholarship deadlines, intakes, community events — filterable by destination.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is JapaBot?", "content_blocks": [{"id": "faq-tools-a7", "type": "content", "visible": true, "props": {"html": "<p><a href=\"/ai\">JapaBot</a> is the platform''s AI assistant. It answers using Japa.to''s own wiki, guides and community content and links back to sources so you can verify. It is a starting point, not a replacement for professional advice.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the remittance rate tracker?", "content_blocks": [{"id": "faq-tools-a8", "type": "content", "visible": true, "props": {"html": "<p>It compares live transfer rates across corridors so you can see which provider actually delivers the most money home — check it before every send.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Learning & profile", "icon": "GraduationCap", "content_blocks": [{"id": "faq-learning", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "What is Japa Academy?", "content_blocks": [{"id": "faq-learning-a0", "type": "content", "visible": true, "props": {"html": "<p><a href=\"/academy\">Japa Academy</a> is the learning arm of the platform — structured tracks on applications, documents, budgeting and settling in, with progress tracking and shareable certificates that show on your profile.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What shows on my public profile?", "content_blocks": [{"id": "faq-learning-a1", "type": "content", "visible": true, "props": {"html": "<p>Your avatar, bio, journey stage, spaces, posts and earned certificates — you choose the visibility of each part in Settings. A pseudonymous username is fine; your legal name is never required.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is the dashboard?", "content_blocks": [{"id": "faq-learning-a2", "type": "content", "visible": true, "props": {"html": "<p>The <a href=\"/dashboard\">dashboard</a> is your hub: continue-learning cards, your certificates, analytics on your posts, and shortcuts into Academy and Docs.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How does mentorship work?", "content_blocks": [{"id": "faq-learning-a3", "type": "content", "visible": true, "props": {"html": "<p>Browse <a href=\"/mentors\">mentors</a> by destination or profession, send a request, and if accepted a DM thread opens automatically. Matching weighs keyword overlap and similarity. Mentors are community members, not paid consultants — never pay a mentor for a ''guaranteed'' outcome.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What is Ask an Expat?", "content_blocks": [{"id": "faq-learning-a4", "type": "content", "visible": true, "props": {"html": "<p>AMA threads are scheduled Q&A sessions where a settled member answers community questions live. Watch the calendar for upcoming sessions or request a topic.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What are achievements and the leaderboard?", "content_blocks": [{"id": "faq-learning-a5", "type": "content", "visible": true, "props": {"html": "<p>Helpful activity — answers, guides, reports, mentoring — earns achievements and XP. The <a href=\"/achievements\">achievement feed</a> and <a href=\"/leaderboard\">leaderboard</a> are opt-in recognition, not a competition requirement.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Credits & marketplace", "icon": "Wallet", "content_blocks": [{"id": "faq-payments", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "What are credits and how do I get them?", "content_blocks": [{"id": "faq-payments-a0", "type": "content", "visible": true, "props": {"html": "<p>Credits are the platform''s optional currency for premium actions — highlighted listings, certain form submissions, promotional placements. Buy them with Paystack or Stripe in your wallet; prices are always shown before you pay.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Can I get a refund?", "content_blocks": [{"id": "faq-payments-a1", "type": "content", "visible": true, "props": {"html": "<p>If a paid feature fails to deliver, contact us via the <a href=\"/contact\">contact form</a> and we will make it right. Otherwise purchases are final as described in the <a href=\"/terms\">Terms of Service</a>.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I list a service or business?", "content_blocks": [{"id": "faq-payments-a2", "type": "content", "visible": true, "props": {"html": "<p>Post it in the <a href=\"/services\">Service Directory</a> — geo-indexed so movers in your area can find you. Keep it honest: fake reviews and disguised advertising are removed under the <a href=\"/rules\">community rules</a>.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Is there a jobs board?", "content_blocks": [{"id": "faq-payments-a3", "type": "content", "visible": true, "props": {"html": "<p>Yes — <a href=\"/jobs\">Jobs</a> lists relocation-friendly roles and sponsorship-track employers. Employers can post openings; always verify any ''guaranteed sponsorship'' claim before paying for anything.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How does advertising work?", "content_blocks": [{"id": "faq-payments-a4", "type": "content", "visible": true, "props": {"html": "<p>Self-serve ad slots let you promote to specific communities — create a campaign from your dashboard. Ads are clearly labelled and never read your personal data.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Are there member deals or discounts?", "content_blocks": [{"id": "faq-payments-a5", "type": "content", "visible": true, "props": {"html": "<p>Check <a href=\"/deals\">Deals</a> — vetted partner offers and coupons for movers (insurance, transfers, flights, services). Every deal shows its terms before you redeem.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Is there a newsletter?", "content_blocks": [{"id": "faq-payments-a6", "type": "content", "visible": true, "props": {"html": "<p>Yes — subscribe on the homepage or in Settings for periodic digests of new destinations, guides and community highlights. Unsubscribe links work in every email.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do referrals work?", "content_blocks": [{"id": "faq-payments-a7", "type": "content", "visible": true, "props": {"html": "<p>Share your referral link and earn credit when people you invite join and engage. Referral rewards and rules are in your dashboard — spamming links gets them revoked.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Safety & moderation", "icon": "Shield", "content_blocks": [{"id": "faq-safety", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "How do you handle scam offers?", "content_blocks": [{"id": "faq-safety-a0", "type": "content", "visible": true, "props": {"html": "<p>Migration scams are common — fake agents, ''guaranteed visa'' schemes, forged documents. We run a dedicated <a href=\"/scam-alerts\">Scam Alert board</a>, moderate reports daily, and permanently remove accounts that facilitate fraud. Never pay anyone who promises a guaranteed outcome, and never share documents with strangers.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I report a post or member?", "content_blocks": [{"id": "faq-safety-a1", "type": "content", "visible": true, "props": {"html": "<p>Use the report option on any post or profile, or submit details through the <a href=\"/contact\">contact form</a> under ''Report abuse''. For scams and fake-agent schemes specifically, post to the <a href=\"/scam-alerts\">Scam Alert board</a> so the whole community benefits.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How does moderation work?", "content_blocks": [{"id": "faq-safety-a2", "type": "content", "visible": true, "props": {"html": "<p>Community moderators and the Japa.to team review reports using a graduated enforcement ladder — note, warning, restriction, suspension, ban — detailed in the <a href=\"/rules\">community rules</a>. Fraud and scams skip the ladder entirely.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Can I appeal a moderation decision?", "content_blocks": [{"id": "faq-safety-a3", "type": "content", "visible": true, "props": {"html": "<p>Yes — open a support ticket from your account and a different reviewer takes a second look. Explain what happened calmly; most honest mistakes get reversed.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Can I claim an organization or university page?", "content_blocks": [{"id": "faq-safety-a4", "type": "content", "visible": true, "props": {"html": "<p>If you officially represent a university, employer or organisation on the platform, use the ownership-claim flow on its page — verified claims get admin rights over the profile after our review.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Can I share my own services or business?", "content_blocks": [{"id": "faq-safety-a5", "type": "content", "visible": true, "props": {"html": "<p>Genuine recommendations are welcome; drive-by advertising is not. Commercial posts belong in the <a href=\"/services\">Service Directory</a>, and undisclosed self-promotion is removed under the <a href=\"/rules\">community rules</a>.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}, {"label": "Account & privacy", "icon": "UserCog", "content_blocks": [{"id": "faq-account", "type": "accordion", "visible": true, "props": {"preset": "faq", "layout": "accordion", "searchable": true, "items": [{"title": "Can I stay anonymous or pseudonymous?", "content_blocks": [{"id": "faq-account-a0", "type": "content", "visible": true, "props": {"html": "<p>You choose a username that does not have to be your legal name, and you control what appears on your public profile. For sensitive topics — visa denials, finances, scams — many members post under a pseudonym. Do not post other people''s private details regardless.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I secure my account?", "content_blocks": [{"id": "faq-account-a1", "type": "content", "visible": true, "props": {"html": "<p>Use a strong unique password and enable two-factor authentication in Settings. We will never ask for your password, one-time codes or wallet PIN — anyone who does is not from Japa.to.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "What data do you collect?", "content_blocks": [{"id": "faq-account-a2", "type": "content", "visible": true, "props": {"html": "<p>Only what is needed to run the platform — account details, the content you choose to post, and standard technical logs. The full breakdown, including retention and your rights, is in the <a href=\"/privacy\">Privacy Policy</a>.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I download or delete my data?", "content_blocks": [{"id": "faq-account-a3", "type": "content", "visible": true, "props": {"html": "<p>From <a href=\"/settings\">Settings</a> you can export your data or request account deletion. Deletion follows the process described in the Privacy Policy — your personal data is erased while anonymised community contributions may remain.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "Does Japa.to sell my data?", "content_blocks": [{"id": "faq-account-a4", "type": "content", "visible": true, "props": {"html": "<p>No. We do not sell personal data to anyone, and there are no third-party data brokers on this platform. Advertising slots exist but are served without handing advertisers your personal information.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}, {"title": "How do I change language or theme?", "content_blocks": [{"id": "faq-account-a5", "type": "content", "visible": true, "props": {"html": "<p>Appearance (light, dark, system) and language are in Settings — or the quick toggles in your account menu. The site remembers them across devices via your account, not trackers.</p>", "prose_style": "minimal"}, "style": {"custom_css": "& section { padding: 0.25rem 0 !important; }"}}]}]}}]}], "layout": "pills", "orientation": "horizontal", "initial_tab": 0}}, {"id": "faq-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Still have a question?", "subhead": "Send us a message — a real person reads every one.", "ctas": [{"label": "Contact us", "href": "/contact", "variant": "primary"}], "alignment": "center"}}]'::jsonb, '{"title": "FAQ — Japa.to", "description": "Straight answers about Japa.to accounts, communities, planning tools, the wiki, academy and safety."}'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET
	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Privacy Policy', 'privacy', 'What data Japa.to collects, why, how long it is kept, and the rights and controls you have over it.', 'page', 'published', '[{"id": "privacy-h", "type": "heading", "visible": true, "props": {"text": "Privacy Policy", "level": "h1", "size": "2xl", "align": "center", "eyebrow": "Legal", "subheading": "Last updated: October 18, 2026 · Written to be read, not just filed away."}}, {"id": "privacy-media", "type": "media", "visible": true, "props": {"media": {"media_id": "", "url": "/illustrations/privacy.svg", "alt": "Illustration of a shield protecting personal data"}, "layout": "contained", "lightbox": false}}, {"id": "privacy-intro", "type": "content", "visible": true, "props": {"html": "\n<p><strong>Japa.to</strong> (\"we\", \"us\", \"the platform\") is a community platform for people planning, making and settling into international moves. This policy explains what personal data we collect, why we collect it, how long we keep it, and the control you have over it.</p>\n<p>It applies to japa.to and its sub-domains (including the academy, docs and tools surfaces), the mobile apps, and any feature that links back to this page. If you do not agree with this policy, please do not use the platform.</p>\n<h2>1. What we collect</h2>\n<p>We collect only what the platform needs to work:</p>\n<ul>\n  <li><strong>Account data</strong> — email address, username, password (stored only as a cryptographic hash), and optional sign-in provider identifiers.</li>\n  <li><strong>Profile data</strong> — what you choose to add: display name, bio, avatar, journey stage, origin and destination countries.</li>\n  <li><strong>Content you create</strong> — posts, comments, wiki edits, stories, form submissions, messages you send, and files you upload.</li>\n  <li><strong>Usage data</strong> — pages visited, features used, searches, and aggregate interactions, used to keep the service fast and relevant.</li>\n  <li><strong>Technical data</strong> — IP address, device and browser type, and timestamps, used for security, abuse prevention and rate limiting.</li>\n  <li><strong>Approximate location</strong> — country-level location inferred from IP (GeoIP), used to surface relevant destinations and content. We never collect precise GPS coordinates unless you explicitly share them.</li>\n  <li><strong>Payment metadata</strong> — when you buy credits, our payment processors (Paystack/Stripe) handle card details directly. We receive only the transaction reference, amount and status — never your card number.</li>\n</ul>\n", "prose_style": "article"}}, {"id": "privacy-table", "type": "table", "visible": true, "props": {"columns": [{"key": "category", "label": "Data category"}, {"key": "examples", "label": "Examples"}, {"key": "purpose", "label": "Why we need it"}], "rows": [{"category": "Account", "examples": "Email, username, password hash", "purpose": "Sign-in, security, recovery"}, {"category": "Profile", "examples": "Bio, avatar, journey stage", "purpose": "Public identity, personalised feed"}, {"category": "Content", "examples": "Posts, comments, uploads", "purpose": "Community features you use"}, {"category": "Usage", "examples": "Page views, feature events", "purpose": "Reliability, relevance, product improvement"}, {"category": "Technical", "examples": "IP, device, timestamps", "purpose": "Security, abuse prevention, rate limits"}, {"category": "Location", "examples": "Country from GeoIP", "purpose": "Geo-relevant destinations and content"}, {"category": "Payments", "examples": "Transaction ref, amount", "purpose": "Credit purchases, receipts, fraud checks"}], "sortable": false, "striped": true}}, {"id": "privacy-use", "type": "content", "visible": true, "props": {"html": "\n<h2>2. How we use your data</h2>\n<ul>\n  <li>Provide and secure the platform — authentication, sessions, feeds, messaging, tools.</li>\n  <li>Personalise content — for example geo-aware destination suggestions (you can override this in Settings).</li>\n  <li>Operate credits, payments and marketplace features.</li>\n  <li>Send service emails (verification, security alerts, receipts) and — only if you opt in — newsletters.</li>\n  <li>Moderate the community: investigate reports, prevent scams, spam and abuse.</li>\n  <li>Understand aggregate usage to improve the product. Analytics are privacy-friendly and self-hosted where possible.</li>\n  <li>Comply with legal obligations — for example responding to lawful requests.</li>\n</ul>\n<h2>3. Legal bases (GDPR)</h2>\n<p>Where the GDPR or similar laws apply, we process personal data under: <strong>contract</strong> (providing the service you signed up for), <strong>legitimate interests</strong> (security, fraud prevention, product improvement — balanced against your rights), <strong>consent</strong> (optional features like newsletters, which you can withdraw at any time), and <strong>legal obligation</strong> (records we must keep).</p>\n<h2>4. Who we share data with</h2>\n<p>We do not sell personal data. We share it only with:</p>\n<ul>\n  <li><strong>Infrastructure providers</strong> — hosting, database, file storage and email delivery, bound by data-processing agreements.</li>\n  <li><strong>Payment processors</strong> — Paystack and Stripe, for credit purchases only.</li>\n  <li><strong>AI providers</strong> — limited content context when you use AI features such as JapaBot, never your private messages or full account data.</li>\n  <li><strong>Other members</strong> — content you publish publicly (posts, profile fields marked public) is visible per your visibility settings.</li>\n  <li><strong>Authorities</strong> — only when legally required, and we push back on overbroad requests.</li>\n</ul>\n<h2>5. International transfers</h2>\n<p>Our community is global, so data may be processed in countries outside yours — including where our infrastructure or processors operate. Where required, transfers are protected by standard contractual clauses or an equivalent safeguard.</p>\n<h2>6. How long we keep data</h2>\n<ul>\n  <li><strong>Account data</strong> — kept while your account is active; erased within 30 days of a confirmed deletion request, except records the law requires us to keep (e.g. payment receipts).</li>\n  <li><strong>Public content</strong> — remains until you delete it; on account deletion it is anonymised or removed as described below.</li>\n  <li><strong>Logs and technical data</strong> — retained for a limited period (typically up to 90 days) for security, then aggregated or deleted.</li>\n  <li><strong>Support conversations</strong> — kept while needed to resolve your request and for a short period after.</li>\n</ul>\n<h2>7. Your rights</h2>\n<p>You can exercise these at any time — most are self-serve in <a href=\"/settings\">Settings</a>, and all are available via the <a href=\"/contact\">contact form</a> (choose \"Privacy &amp; data\"):</p>\n<ul>\n  <li><strong>Access</strong> — get a copy of your data (Settings → data export).</li>\n  <li><strong>Correction</strong> — fix inaccurate profile data yourself, or ask us.</li>\n  <li><strong>Erasure</strong> — delete your account; personal data is erased and public contributions anonymised.</li>\n  <li><strong>Portability</strong> — your export is a machine-readable file you can take elsewhere.</li>\n  <li><strong>Objection &amp; restriction</strong> — opt out of newsletters and optional processing.</li>\n  <li><strong>Complaint</strong> — you may also complain to your local data protection authority; we would appreciate the chance to fix things first.</li>\n</ul>\n<h2>8. Security</h2>\n<p>Passwords are hashed, sessions use short-lived tokens, two-factor authentication is available, and access to production data is restricted and audited. No system is perfectly secure — if you suspect a breach or find a vulnerability, please report it via the <a href=\"/contact\">contact form</a> under \"Report abuse\" immediately.</p>\n<h2>9. Children</h2>\n<p>Japa.to is not directed at children under 16, and we do not knowingly collect their data. If you believe a child has created an account, contact us and we will remove it.</p>\n<h2>10. Cookies</h2>\n<p>We use a small set of cookies for sign-in, security and preferences — the full list and your choices are in the <a href=\"/cookies\">Cookie Policy</a>.</p>\n<h2>11. Changes to this policy</h2>\n<p>If we change this policy we will update the date above, and for significant changes we will notify you in the product or by email. Continuing to use Japa.to after a change means you accept the updated policy.</p>\n<h2>12. Contact</h2>\n<p>Privacy questions, requests or complaints: use the <a href=\"/contact\">contact form</a> and choose the \"Privacy &amp; data\" topic.</p>\n", "prose_style": "article"}}, {"id": "privacy-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Want a copy of your data?", "subhead": "Export or delete your data from Settings — no email required.", "ctas": [{"label": "Open Settings", "href": "/settings", "variant": "primary"}, {"label": "Contact us", "href": "/contact", "variant": "ghost"}], "alignment": "center"}}]'::jsonb, '{"title": "Privacy Policy — Japa.to", "description": "How Japa.to collects, uses, retains and protects your personal data — and how to exercise your rights."}'::jsonb, now())
