	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Terms of Service', 'terms', 'The agreement between you and Japa.to: accounts, content, acceptable use, payments, disclaimers and disputes.', 'page', 'published', '[{"id": "terms-h", "type": "heading", "visible": true, "props": {"text": "Terms of Service", "level": "h1", "size": "2xl", "align": "center", "eyebrow": "Legal", "subheading": "Last updated: October 18, 2026 · The agreement between you and Japa.to."}}, {"id": "terms-media", "type": "media", "visible": true, "props": {"media": {"media_id": "", "url": "/illustrations/terms.svg", "alt": "Illustration of a signed agreement document"}, "layout": "contained", "lightbox": false}}, {"id": "terms-body", "type": "content", "visible": true, "props": {"html": "\n<p>Welcome to <strong>Japa.to</strong> (\"we\", \"us\", \"the platform\"). These Terms of Service (\"Terms\") govern your access to and use of japa.to, its sub-domains, mobile apps and related services (the \"Service\"). By creating an account or using the Service, you agree to these Terms and to the <a href=\"/rules\">Community Rules</a>, <a href=\"/privacy\">Privacy Policy</a> and <a href=\"/cookies\">Cookie Policy</a>, which are part of this agreement.</p>\n<h2>1. Who can use the Service</h2>\n<p>You must be at least 16 years old and able to form a binding contract. If you use the Service on behalf of an organisation, you confirm you are authorised to bind it. You may not use the Service if a previous account was terminated for fraud, scams or serious abuse.</p>\n<h2>2. Your account</h2>\n<ul>\n  <li>Provide accurate registration information and keep it current.</li>\n  <li>You are responsible for everything that happens under your account — keep your password and two-factor codes private. We will never ask for them.</li>\n  <li>Tell us immediately via the <a href=\"/contact\">contact form</a> if you suspect unauthorised access.</li>\n  <li>Usernames may not impersonate people or organisations, or infringe others'' rights.</li>\n</ul>\n<h2>3. Your content</h2>\n<ul>\n  <li><strong>You own what you post.</strong> Japa.to does not claim ownership of your posts, comments, wiki edits, stories or uploads.</li>\n  <li>You grant us a non-exclusive, worldwide, royalty-free licence to host, store, display, reproduce and distribute your content <em>as needed to operate and improve the Service</em> — for example showing your post to members, or including an anonymised excerpt in a community digest.</li>\n  <li>You are responsible for your content: it must be accurate to the best of your knowledge, lawful, and yours to share.</li>\n  <li>Wiki contributions are collaborative — you agree they may be edited by other members under the wiki''s review process.</li>\n  <li>We may remove content that violates these Terms or the Community Rules, or that the law requires us to remove.</li>\n</ul>\n<h2>4. Acceptable use</h2>\n<p>You agree not to:</p>\n<ul>\n  <li>Post scams, fraudulent offers, fake documents, \"guaranteed visa\" schemes or any content designed to deceive — this is the single fastest way to lose your account.</li>\n  <li>Harass, threaten, doxx or discriminate against anyone.</li>\n  <li>Facilitate illegal immigration, visa fraud, or the sale of unlawful goods or services.</li>\n  <li>Spam, mass-message, scrape at scale, or manipulate votes, rankings or metrics.</li>\n  <li>Upload malware, probe for vulnerabilities without permission, or interfere with the Service''s operation.</li>\n  <li>Misrepresent your identity, credentials, affiliations or immigration outcomes.</li>\n  <li>Collect other members'' personal data, or publish anyone''s documents, addresses or private details.</li>\n</ul>\n<p>The full conduct standard lives in the <a href=\"/rules\">Community Rules</a>, which are enforceable under these Terms.</p>\n<h2>5. Informational tools &amp; content — not advice</h2>\n<p>Checklists, calculators, wiki pages, courses, community answers and AI assistant responses are <strong>general information, not legal, immigration, financial or professional advice</strong>. Immigration rules change constantly and vary by individual circumstance. Always verify requirements with the official government, embassy or a licensed adviser before acting or paying anyone.</p>\n<h2>6. Credits, payments &amp; marketplace</h2>\n<ul>\n  <li>Some features use platform credits, purchased through our payment processors. Prices are shown before you pay.</li>\n  <li>Credits are a limited, revocable, non-transferable licence to use optional features — they are not money, cannot be withdrawn as cash, and expire only where the law permits.</li>\n  <li>Except where required by law, purchases are final; if a paid feature fails to deliver, contact us and we will make it right.</li>\n  <li>Listings in the service directory and marketplace are provided by third parties — we do not guarantee them. Verify providers yourself before paying.</li>\n</ul>\n<h2>7. Intellectual property</h2>\n<p>The Service — including its design, code, logo and original content — belongs to Japa.to and its licensors. You may not copy, frame or reuse substantial parts of it without permission. Member content remains owned by its authors (Section 3).</p>\n<h2>8. Third-party services &amp; links</h2>\n<p>The Service links to embassies, universities, employers, payment processors and other third parties. We do not control and are not responsible for their content, accuracy or practices — their own terms and policies apply.</p>\n<h2>9. Termination</h2>\n<ul>\n  <li>You may delete your account at any time in <a href=\"/settings\">Settings</a>.</li>\n  <li>We may suspend or terminate accounts that break these Terms or the Community Rules, especially for fraud, scams or safety risks.</li>\n  <li>On termination, your right to use the Service ends; sections on content licence wind-down, disclaimers and liability survive.</li>\n</ul>\n<h2>10. Disclaimers</h2>\n<p>The Service is provided \"as is\" and \"as available\". To the maximum extent the law allows, we disclaim all warranties — including merchantability, fitness for a particular purpose and non-infringement — and we do not promise the Service will be uninterrupted, error-free or that community-provided information is accurate.</p>\n<h2>11. Limitation of liability</h2>\n<p>To the maximum extent permitted by law, Japa.to is not liable for indirect, incidental, special or consequential damages — including lost profits, lost data, or losses from decisions made based on community content or tools. Our total liability for any claim is limited to the greater of the amount you paid us in the 12 months before the claim or USD 100. Nothing in these Terms limits liability that cannot legally be limited.</p>\n<h2>12. Indemnity</h2>\n<p>You agree to indemnify Japa.to against claims and losses arising from your content, your violation of these Terms, or your violation of anyone else''s rights.</p>\n<h2>13. Governing law &amp; disputes</h2>\n<p>These Terms are governed by the laws of the jurisdiction in which Japa.to is established, without regard to conflict-of-law rules. Before filing any claim you agree to try to resolve the dispute informally — contact us first; most issues resolve quickly that way. Mandatory consumer-protection rights in your country remain unaffected.</p>\n<h2>14. Changes to these Terms</h2>\n<p>We may update these Terms as the Service evolves. We will update the date above and, for material changes, notify you in the product or by email. Continued use after changes take effect means you accept them.</p>\n<h2>15. Contact</h2>\n<p>Questions about these Terms: use the <a href=\"/contact\">contact form</a> and choose the \"General enquiry\" topic.</p>\n", "prose_style": "article"}}, {"id": "terms-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Know the rules of the road", "subhead": "The Community Rules explain what is and isn''t allowed — in plain language.", "ctas": [{"label": "Read Community Rules", "href": "/rules", "variant": "primary"}], "alignment": "center"}}]'::jsonb, '{"title": "Terms of Service — Japa.to", "description": "The terms governing your use of Japa.to — accounts, content licence, acceptable use, credits and liability."}'::jsonb, now())
