	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Community Rules & Guidelines', 'rules', 'The conduct standard that keeps Japa.to trustworthy: respect, honesty, safety, and zero tolerance for scams.', 'page', 'published', '[{"id": "rules-hero", "type": "hero", "visible": true, "props": {"eyebrow": "Community guidelines", "headline": "The rules that keep this community worth trusting.", "subhead": "Japa.to works because people share honestly and look out for each other. These rules protect that — especially where scams target people planning a move.", "layout": "split", "media": {"media_id": "", "url": "/illustrations/rules.svg", "alt": "Illustration of a balanced scale over community members"}, "ctas": [{"label": "Report a violation", "href": "/contact", "variant": "ghost"}]}}, {"id": "rules-principles", "type": "card_grid", "visible": true, "props": {"cards": [{"icon": "HeartHandshake", "title": "Respect people", "description": "Debate ideas, not people. Every member is someone''s son, daughter, friend — or fellow anxious applicant."}, {"icon": "BadgeCheck", "title": "Share honestly", "description": "Real experiences, clearly labelled opinions, and sources for claims. No invented success stories."}, {"icon": "ShieldCheck", "title": "Keep each other safe", "description": "Migration attracts predators. We remove scams fast and help each other spot them."}], "card_variant": "feature", "layout": "grid", "columns": 3, "responsive_columns": {"tablet": 2, "mobile": 1}}}, {"id": "rules-body", "type": "content", "visible": true, "props": {"html": "\n<h2>The rules</h2>\n<h3>1. Treat people with respect</h3>\n<p>No harassment, bullying, hate speech or discrimination — including by nationality, ethnicity, religion, gender, sexuality or disability. Disagreement is fine; contempt is not. No threats, incitement or targeted mockery of someone''s immigration setback.</p>\n<h3>2. No scams or fraud — zero tolerance</h3>\n<ul>\n  <li>No \"guaranteed visa\", paid-slot or backdoor offers. Nobody can guarantee a visa outcome.</li>\n  <li>No fake job offers, forged documents, or agent services that require payment through untraceable channels (gift cards, crypto, wire to personal accounts).</li>\n  <li>No impersonating embassies, universities, officials or other members.</li>\n  <li>Suspect something? Post to the <a href=\"/scam-alerts\">Scam Alert board</a> — it protects everyone.</li>\n</ul>\n<h3>3. Share accurate information</h3>\n<p>Immigration rules change fast. State what you know first-hand, flag what you believe but can''t verify, and link official sources for visa, fee and deadline claims. Intentionally misleading people about requirements, timelines or costs is a serious violation — bad information costs people real money and real years.</p>\n<h3>4. Protect privacy — yours and theirs</h3>\n<ul>\n  <li>Never post anyone''s personal documents, passport data, addresses, phone numbers or private messages without consent.</li>\n  <li>Blur out personal details when sharing screenshots of letters or decisions.</li>\n  <li>Don''t pressure members to reveal their identity, employer or case specifics.</li>\n</ul>\n<h3>5. No spam or deceptive promotion</h3>\n<ul>\n  <li>Businesses and services belong in the <a href=\"/services\">Service Directory</a>, clearly labelled — not disguised as member recommendations.</li>\n  <li>No mass DMing, referral-link flooding, vote manipulation or engagement bait.</li>\n  <li>Disclose affiliations: if you benefit from a recommendation, say so.</li>\n</ul>\n<h3>6. Keep it legal</h3>\n<p>No content that facilitates crimes: forged documents, visa fraud techniques, smuggling, or buying/selling unlawful services. Discussion of legal processes — even difficult ones — is welcome; instructions for breaking the law are not.</p>\n<h3>7. Post in the right place</h3>\n<p>Keep posts in their relevant space, use the right content type, and don''t cross-post the same thread everywhere. Moderators may move or merge content that belongs elsewhere.</p>\n<h3>8. Handle sensitive topics with care</h3>\n<p>Mental health, denials, deportation, family separation — these threads involve real people at their lowest. Be constructive. Content promoting self-harm or exploiting vulnerable members is removed immediately and may be escalated.</p>\n", "prose_style": "article"}}, {"id": "rules-enforcement", "type": "content", "visible": true, "props": {"html": "\n<h2>How enforcement works</h2>\n<p>Moderators — community members plus the Japa.to team — enforce these rules using a graduated ladder:</p>\n<table>\n  <thead><tr><th>Step</th><th>What happens</th></tr></thead>\n  <tbody>\n    <tr><td><strong>1. Note</strong></td><td>Content removed with a polite explanation — most first issues end here.</td></tr>\n    <tr><td><strong>2. Warning</strong></td><td>A formal warning on your account record for repeated or more serious violations.</td></tr>\n    <tr><td><strong>3. Restriction</strong></td><td>Temporary limits on posting, messaging or specific spaces.</td></tr>\n    <tr><td><strong>4. Suspension</strong></td><td>Time-limited account suspension for serious or repeated violations.</td></tr>\n    <tr><td><strong>5. Ban</strong></td><td>Permanent removal for scams, fraud, threats, or persistent abuse. Scam and fraud violations skip the ladder entirely.</td></tr>\n  </tbody>\n</table>\n<h2>Reporting &amp; appeals</h2>\n<ul>\n  <li><strong>Report:</strong> use the report option on any post or profile, the <a href=\"/scam-alerts\">Scam Alert board</a> for fraud, or the <a href=\"/contact\">contact form</a> (topic \"Report abuse\"). Reports are confidential and reviewed by humans.</li>\n  <li><strong>Appeal:</strong> think a moderation decision was wrong? Open a ticket from your account and a different reviewer takes a second look.</li>\n</ul>\n<p>These rules are enforced alongside the <a href=\"/terms\">Terms of Service</a>. They evolve with the community — material changes are announced, not slipped in quietly.</p>\n", "prose_style": "article"}}, {"id": "rules-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Seen something that breaks these rules?", "subhead": "Reports are confidential and reviewed by a human — usually within a day.", "ctas": [{"label": "Report it", "href": "/contact", "variant": "primary"}, {"label": "Scam alerts", "href": "/scam-alerts", "variant": "ghost"}], "alignment": "center"}}]'::jsonb, '{"title": "Community Rules — Japa.to", "description": "Community rules and moderation policy: respectful conduct, no scams or fraud, accurate information, privacy and enforcement."}'::jsonb, now())
