	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Cookie Policy', 'cookies', 'The short list of cookies Japa.to sets — sessions, security and preferences — and how to control them.', 'page', 'published', '[{"id": "cookies-h", "type": "heading", "visible": true, "props": {"text": "Cookie Policy", "level": "h1", "size": "2xl", "align": "center", "eyebrow": "Legal", "subheading": "Last updated: October 18, 2026 · A short list, because we use few cookies."}}, {"id": "cookies-media", "type": "media", "visible": true, "props": {"media": {"media_id": "", "url": "/illustrations/cookies.svg", "alt": "Illustration of a cookie with a settings gear"}, "layout": "contained", "lightbox": false}}, {"id": "cookies-intro", "type": "content", "visible": true, "props": {"html": "\n<p>Cookies are small text files a site stores on your device. Japa.to uses a deliberately small set — enough to keep you signed in, keep the site secure, and remember your preferences. We do not use advertising trackers or third-party profiling cookies.</p>\n<h2>Cookies we set</h2>\n", "prose_style": "article"}}, {"id": "cookies-table", "type": "table", "visible": true, "props": {"columns": [{"key": "name", "label": "Cookie"}, {"key": "category", "label": "Category"}, {"key": "purpose", "label": "Purpose"}, {"key": "duration", "label": "Duration"}], "rows": [{"name": "jc_token", "category": "Strictly necessary", "purpose": "Your signed-in session", "duration": "Short-lived; renewed automatically"}, {"name": "jc_refresh", "category": "Strictly necessary", "purpose": "Securely refreshes your session", "duration": "Up to 30 days"}, {"name": "csrf_token", "category": "Strictly necessary", "purpose": "Protects actions from cross-site forgery", "duration": "Session"}, {"name": "jc_theme", "category": "Preferences", "purpose": "Remembers light/dark/system appearance", "duration": "1 year"}, {"name": "jc_locale", "category": "Preferences", "purpose": "Remembers your language", "duration": "1 year"}, {"name": "nav_pin_override", "category": "Preferences", "purpose": "Remembers your nav rail preference", "duration": "1 year"}, {"name": "jc_journey_token", "category": "Preferences", "purpose": "Keeps guest checklist/assessment progress", "duration": "90 days"}], "sortable": false, "striped": true}}, {"id": "cookies-body", "type": "content", "visible": true, "props": {"html": "\n<h2>Categories explained</h2>\n<ul>\n  <li><strong>Strictly necessary</strong> — the Service cannot work without these. They cannot be switched off.</li>\n  <li><strong>Preferences</strong> — remember choices like theme and language. The site still works without them; it just won''t remember you.</li>\n  <li><strong>Analytics</strong> — we use privacy-friendly, aggregate analytics to understand which features help people. Where analytics run, they do not use cross-site tracking cookies or build individual advertising profiles.</li>\n</ul>\n<h2>What we do not use</h2>\n<ul>\n  <li>No third-party advertising or retargeting cookies.</li>\n  <li>No social-media tracking pixels.</li>\n  <li>No sale of cookie-derived data to brokers.</li>\n</ul>\n<h2>Managing cookies</h2>\n<p>You can block or delete cookies in your browser settings at any time. Blocking strictly-necessary cookies will sign you out and parts of the site will stop working — for obvious reasons, a session cookie is required to stay signed in.</p>\n<p>Browser-level \"Do Not Track\" signals are respected for analytics where the browser sends one.</p>\n<h2>Changes</h2>\n<p>If we add a new cookie category we will update this page and, where required, ask for consent first. Questions: <a href=\"/contact\">contact us</a> or see the <a href=\"/privacy\">Privacy Policy</a>.</p>\n", "prose_style": "article"}}, {"id": "cookies-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Prefer fewer cookies?", "subhead": "Your privacy controls — data export, deletion and more — live in Settings.", "ctas": [{"label": "Open Settings", "href": "/settings", "variant": "primary"}, {"label": "Privacy Policy", "href": "/privacy", "variant": "ghost"}], "alignment": "center"}}]'::jsonb, '{"title": "Cookie Policy — Japa.to", "description": "Which cookies Japa.to sets, what each does, and how to manage or block them."}'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET
	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

INSERT INTO pages (id, title, slug, description, page_type, status, blocks, meta, published_at)
VALUES (gen_random_uuid(), 'Trust & Safety', 'safety', 'How Japa.to keeps the community safe — moderation, scam alerts, privacy controls — and how to spot a migration scam.', 'page', 'published', '[{"id": "safety-hero", "type": "hero", "visible": true, "props": {"eyebrow": "Trust & safety", "headline": "Your move is too important to leave to scammers.", "subhead": "How Japa.to keeps the community trustworthy — and how to protect yourself from the schemes that target people planning to relocate.", "layout": "split", "media": {"media_id": "", "url": "/illustrations/safety.svg", "alt": "Illustration of a protective umbrella over community members"}, "ctas": [{"label": "Report a scam", "href": "/scam-alerts", "variant": "primary"}, {"label": "Community rules", "href": "/rules", "variant": "ghost"}]}}, {"id": "safety-how-h", "type": "heading", "visible": true, "props": {"text": "How we keep you safe", "level": "h2", "size": "xl", "align": "center"}}, {"id": "safety-how", "type": "card_grid", "visible": true, "props": {"cards": [{"icon": "ShieldAlert", "title": "Scam alert board", "description": "A community-run early-warning system for fake agents, forged offers and visa schemes — moderated daily.", "cta": {"label": "See recent alerts", "href": "/scam-alerts", "variant": "link"}}, {"icon": "UserCheck", "title": "Human moderation", "description": "Reports are reviewed by people, not just filters. Moderators act on scams, harassment and misinformation.", "cta": {"label": "Read the rules", "href": "/rules", "variant": "link"}}, {"icon": "Lock", "title": "Privacy controls", "description": "Pseudonymous profiles, granular visibility, self-serve data export and deletion.", "cta": {"label": "Privacy policy", "href": "/privacy", "variant": "link"}}, {"icon": "LifeBuoy", "title": "Real support", "description": "Every contact message is read by a person — and we never ask for passwords or codes.", "cta": {"label": "Contact us", "href": "/contact", "variant": "link"}}], "card_variant": "feature", "layout": "grid", "columns": 2, "responsive_columns": {"tablet": 2, "mobile": 1}}}, {"id": "safety-tips-h", "type": "heading", "visible": true, "props": {"text": "Spot a migration scam before it costs you", "level": "h2", "size": "xl", "align": "center", "eyebrow": "Protect yourself", "subheading": "These patterns appear in almost every relocation scam we see reported."}}, {"id": "safety-tips", "type": "content", "visible": true, "props": {"html": "\n<ul>\n  <li><strong>\"Guaranteed visa\" or \"100% success rate\"</strong> — no agent, consultant or insider can guarantee an outcome. Anyone who claims otherwise is lying to you.</li>\n  <li><strong>Payment through untraceable channels</strong> — gift cards, crypto, wire transfers to personal accounts, or mobile-money numbers that don''t match a registered business.</li>\n  <li><strong>Artificial urgency</strong> — \"slots close tonight\", \"only 2 seats left\", pressure to pay before you can verify anything.</li>\n  <li><strong>Too-cheap offers</strong> — fees dramatically below official costs, or \"job offers\" that require an upfront payment from <em>you</em>.</li>\n  <li><strong>Unofficial documents</strong> — forged offer letters, fake embassy emails, look-alike domains. Verify on the official government site — never through a link a stranger sent you.</li>\n  <li><strong>Refusal of video calls or verifiable addresses</strong> — legitimate consultants put their name, registration and office on the line.</li>\n</ul>\n<p><strong>Before you pay anyone</strong>: search their name on the <a href=\"/scam-alerts\">Scam Alert board</a>, verify their registration with the relevant regulator, and ask the community — someone has usually seen the pitch before.</p>\n<h2>If you''ve been scammed</h2>\n<ul>\n  <li>Report it on the <a href=\"/scam-alerts\">Scam Alert board</a> — your report stops the next person.</li>\n  <li>Contact your bank or payment provider immediately; some transfers can be recalled.</li>\n  <li>Report to local authorities and, for fake job/visa schemes, the genuine embassy or institution being impersonated.</li>\n  <li>Tell us via the <a href=\"/contact\">contact form</a> so we can remove the account and warn members.</li>\n</ul>\n<p>There is no shame in being caught — these schemes are built by professionals. Reporting quickly is what protects the community.</p>\n", "prose_style": "article"}}, {"id": "safety-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Suspicious offer? Don''t sit on it.", "subhead": "A 2-minute report can save someone their life savings.", "ctas": [{"label": "Report a scam", "href": "/scam-alerts", "variant": "primary"}], "alignment": "center"}}]'::jsonb, '{"title": "Trust & Safety — Japa.to", "description": "Community safety at Japa.to: scam reporting, human moderation and practical tips to spot migration fraud."}'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET
	title = EXCLUDED.title,
	description = EXCLUDED.description,
	page_type = EXCLUDED.page_type,
	status = EXCLUDED.status,
	blocks = EXCLUDED.blocks,
	meta = EXCLUDED.meta,
	published_at = COALESCE(pages.published_at, now()),
	updated_at = now();

-- ── 4. Footer menu links ────────────────────────────────────────────────
-- main_footer already linked /about, /privacy and /terms (previously 404s).
-- Insert the remaining pages and shift the guest auth links to the end.

UPDATE menu_items SET sort_order = 12 WHERE menu_id = (SELECT id FROM menus WHERE slug = 'main_footer') AND url = '/signup';
UPDATE menu_items SET sort_order = 13 WHERE menu_id = (SELECT id FROM menus WHERE slug = 'main_footer') AND url = '/login';

INSERT INTO menu_items (menu_id, label, url, sort_order, visibility)
SELECT m.id, v.label, v.url, v.sort_order, 'all'
FROM menus m
JOIN (VALUES
	('Contact',         '/contact', 7),
	('FAQ',             '/faq',     8),
	('Community Rules', '/rules',   9),
	('Cookie Policy',   '/cookies', 10),
	('Safety',          '/safety',  11)
) AS v(label, url, sort_order) ON true
WHERE m.slug = 'main_footer'
  AND NOT EXISTS (
	SELECT 1 FROM menu_items mi WHERE mi.menu_id = m.id AND mi.url = v.url
  );

COMMIT;
